scriptsCode.doAction:
// (保存)GeneralAction1.doAction
debugger;

var selNode = PTTree1.getSelectedNodes();
if(selNode != null && selNode[0].key == "0"){
    // FormAlert.showWarnAlert('默认根节点无法使用保存！');
    return 0;
}

//校验逻辑
let caption = MenuFormTextInput.getValue();
let formType = FormTypeFormComboBox.getValue();
let displayType = DisplayTypeFormComboBox.getValue();
let isVisible = FormSwitchButton2.getValue() == "" ? 0 : 1;
if(caption == null || caption.trim() == ""){
    FormAlert.showWarnAlert('[菜单名称]不能为空！');
    return 0;
}
if(formType == null || formType == ""){
    FormAlert.showWarnAlert('[表单类型]不能为空！');
    return 0;
}
if(displayType == null || displayType == ""){
    FormAlert.showWarnAlert('[打开方式]不能为空！');
    return 0;
}
if(formType == "ReactForm"){
    if(displayType == null || displayType == ""){
        FormAlert.showWarnAlert('[打开方式]不能为空！');
        return 0;
    }

    var form = DataSetFieldComboBox2.getValue();
    if(form == null || form == ""){
        FormAlert.showWarnAlert('[表单编号]不能为空！');
        return 0;
    }
    var switchFlow = FormSwitchButton3.getValue();
    if(switchFlow == "1"){
        var flow = DataSetFieldComboBox3.getValue();
        if(flow == ""){
            FormAlert.showWarnAlert('[关联流程]不能为空！');
            return 0;
        }
    }
}
var addAttr = "";
if(formType == "ReactComp"){
    var form = DataSetFieldComboBox5.getValue();
    if(form == null || form == ""){
        FormAlert.showWarnAlert('[硬编码组件]不能为空！');
        return 0;
    } else {
        addAttr += "formID=" + form + ";";
    }
}

if(formType == "IFrame"){
    var form = FormTextInput2.getValue();
    if(form == null || form == ""){
        FormAlert.showWarnAlert('[webURL]不能为空！');
        return 0;
    } else {
        addAttr += "webURL=" + form + ";";
    }
}

///相关表单判重、组织数据逻辑
var formDataSet = AGGrid1.getDataSet();
var formsArr = formDataSet.getRowSetArray();
//判重
let formDuplicates = formsArr.some((obj, index) => {
    return formsArr.filter((o, i) => o.getString("FORM_CODE","") === obj.getString("FORM_CODE","")).length > 1;
});
if(formDuplicates){
    FormAlert.showWarnAlert('【相关表单】中存在重复项，请检查！');
    return 0;
}

var relatedForms = [];
for(var i = 0; i < formDataSet.getRowCount(); i++){
   relatedForms.push(Object.fromEntries(formDataSet.getRowSet(i).getDataMap()));
   var FORM_CODE = formDataSet.getRowSet(i).getString("FORM_CODE","");

   if(FORM_CODE == ""){
        FormAlert.showWarnAlert('【功能权限】的第'+(i+1)+'行表单编号不能为空，请检查！');
        return 0;
    }

}
selNode[0]["extProps"].relatedForms = JSON.stringify(relatedForms);


///权限标识判重、组织数据逻辑
var authDataSet = AGGrid3.getDataSet();
var authArr = authDataSet.getRowSetArray();
//判重
let authDuplicates = authArr.some((obj, index) => {
    return authArr.filter((o, i) => o.getString("F_EXTSTR04","") === obj.getString("F_EXTSTR04","")).length > 1;
});
if(authDuplicates){
    FormAlert.showWarnAlert('【功能权限】存在重复项，请检查！');
    return 0;
}

var authFlags = [];
for(var i = 0; i < authDataSet.getRowCount(); i++){
   authFlags.push(Object.fromEntries(authDataSet.getRowSet(i).getDataMap()));
   var F_EXTSTR04 = authDataSet.getRowSet(i).getString("F_EXTSTR04","");
   var F_GNMC = authDataSet.getRowSet(i).getString("F_GNMC","");

   if(F_EXTSTR04 == "" || F_GNMC ==""){
        FormAlert.showWarnAlert('【功能权限】的第'+(i+1)+'行表[权限KEY]和[权限描述]不能为空，请检查！');
        return 0;
    }

}
selNode[0]["extProps"].authFlags = JSON.stringify(authFlags);

//高级参数:判重，组织数据
let advDataSet = AGGrid4.getDataSet();
let advArr = advDataSet.getRowSetArray();
//判重
let advDuplicates = advArr.some((obj, index) => {
    return advArr.filter((o, i) => o.getString("ADV_CODE","") === obj.getString("ADV_CODE","")).length > 1;
});
if(advDuplicates){
    FormAlert.showWarnAlert('【高级参数】存在重复项，请检查！');
    return 0;
}
let advStr = "";
for(var i = 0; i < advDataSet.getRowCount(); i++){
    let rowSet = advDataSet.getRowSet(i);
    let advCode = rowSet.getString("ADV_CODE","");
    let advValue = rowSet.getString("ADV_VALUE","");
    if(advCode == "" || advValue ==""){
        FormAlert.showWarnAlert('【高级参数】的第'+(i+1)+'行表[编码]和[值]不能为空，请检查！');
        return 0;
    }

    advStr = advStr + advCode + "=" + advValue + ";";
}
debugger
let attrStr = "formType="+formType+";displayType="+displayType+";isVisible="+isVisible+";caption="+caption+";";
attrStr += addAttr;
selNode[0]["extProps"].VTREE_ATTR = attrStr+advStr;
selNode[0]["extProps"].VTREE_ISROOT = 0;
selNode[0]["extProps"].VTREE_MX = 1;
//selNode[0]["extProps"].VTREE_JS = 1;
selNode[0]["extProps"].F_STAU = "1";
selNode[0]["extProps"].SYS_ID = "MHZX";
// selNode[0]["extProps"].AUTH_ENABLE = "1";
selNode[0]["extProps"].AUTH_ENABLE = FormSwitchButton1.getValue();
selNode[0]["extProps"].VTREE_CONTENTVIEW = DataSetFieldComboBox2.getValue()+".form1";
// selNode[0]["extProps"].F_GUID = UUID();
// selNode[0]["extProps"].SYS_ID = 'MHZX';

PTTree1.updateNode(selNode[0]);
let editType = modelContainer.getValue('editType', '');
//PTTree1.save();
debugger
if(editType == 'create') {
    modelContainer.setValue('editType', '');
    PTTree1.save();
}else {
    //执行保存
    MDMSaveAction2.doAction();
}

